import{_ as e,o as i,c as a,a5 as o}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"十四、数据库版本管理工具Flyway","description":"","frontmatter":{"title":"十四、数据库版本管理工具Flyway","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端快速开发/十四、数据库版本管理工具Flyway.md","filePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端快速开发/十四、数据库版本管理工具Flyway.md"}'),t={name:"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端快速开发/十四、数据库版本管理工具Flyway.md"};function d(c,l,r,p,s,n){return i(),a("div",null,[...l[0]||(l[0]=[o('<div><p>前言 在项目中，经常会进行版本的升级。在版本升级时，就会牵扯到数据库的升级。 平时可能我们有一个文件系统保存<code>SQL</code>脚本，需要升到哪个版本就执行对应的<code>SQL</code>脚本。这样很麻烦，并且容易出错。</p><p><code>Flyway</code>是独立于数据库的应用、管理并跟踪数据库变更的数据库版本管理工具。 用通俗的话讲，<code>Flyway</code>可以像<code>Git</code>管理不同人的代码那样，管理不同人的<code>SQL</code>脚本，从而做到数据库同步。</p><p><strong>具体实现</strong><code>Maven</code>依赖</p><ul><li>&lt;dependencies&gt;</li><li>&lt;dependency&gt;</li><li>&lt;groupId&gt;org.flywaydb&lt;/groupId&gt;</li><li>&lt;artifactId&gt;flyway-core&lt;/artifactId&gt;</li><li>&lt;version&gt;6.0.8&lt;/version&gt;</li><li>&lt;/dependency&gt;</li><li>&lt;/dependencies&gt;</li></ul><p>插件依赖：</p><ul><li>&lt;plugins&gt;</li><li>&lt;plugin&gt;</li><li>&lt;groupId&gt;org.flywaydb&lt;/groupId&gt;</li><li>&lt;artifactId&gt;flyway-maven-plugin&lt;/artifactId&gt;</li><li>&lt;version&gt;6.0.8&lt;/version&gt;</li><li>&lt;/plugin&gt;</li><li>&lt;/plugins&gt;</li></ul><p><strong>文件位置</strong><code>SQL</code>文件存放的目录默认为：<code>db/migration</code></p><p>也可以通过配置<code>spring.flyway.locations=classpath:db/migration</code>修改。</p><p><strong>命名规范</strong><code>SQL</code>文件命名规范：前缀 <code>+</code> 版本号 <code>+</code> 双下划线 <code>+</code> 描述 <code>+</code> 后缀</p><p>也可以通过配置对命名规范进行修改，如下：</p><ul><li>flyway:</li><li><h1 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>前缀，默认</p><ul><li>V</li><li>sql-migration-prefix: V</li><li><h1 id="-1" tabindex="-1"><a class="header-anchor" href="#-1" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>文件分隔符，默认</p><ul><li>__</li><li>sql-migration-separator: __</li><li><h1 id="-2" tabindex="-1"><a class="header-anchor" href="#-2" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>后缀，默认</p><ul><li>.sql</li><li>sql-migration-suffixes: .sql</li></ul><p>版本号可以使用如下结构：</p><ul><li><code>1</code></li><li><code>001</code></li><li><code>5.2</code></li><li><code>1.2.3.4.5.6.7.8.9</code></li><li><code>205.68</code></li><li><code>20200616113556</code></li><li><code>2020.6.16.11.35.56</code></li><li><code>2020.06.16.11.35.56</code></li></ul><p><code>SQL</code><strong>文件</strong><code>SQL</code>文件里的内容就是需要更新的<code>SQL</code>脚本。比如：</p><p>DROPTABLEIF EXISTS<code>sys_user</code>; CREATETABLE<code>sys_user</code> ( <code>id</code> INT(11) NOTNULLAUTO_INCREMENT, <code>account</code> VARCHAR(40) NOTNULLCOMMENT &#39; 用户名</p><ul><li>&#39;,</li><li><code>password</code> VARCHAR(255) NOTNULLCOMMENT &#39;</li></ul><p>密码</p><ul><li>&#39;,</li><li><code>nickname</code> VARCHAR(60) DEFAULTNULLCOMMENT &#39;</li></ul><p>昵称</p><ul><li>&#39;,</li><li><code>email</code> VARCHAR(40) DEFAULTNULLCOMMENT &#39;</li></ul><p>邮箱</p><ul><li>&#39;,</li><li><code>phone</code> VARCHAR(11) DEFAULTNULLCOMMENT &#39;</li></ul><p>电话</p><ul><li>&#39;,</li><li><code>create_time</code> datetime DEFAULTNULLCOMMENT &#39;</li></ul><p>创建时间</p><ul><li>&#39;,</li><li><code>create_user</code> VARCHAR(11) DEFAULTNULLCOMMENT &#39;</li></ul><p>创建人</p><ul><li>&#39;,</li><li><code>modify_time</code> datetime DEFAULTNULLCOMMENT &#39;</li></ul><p>修改时间</p><ul><li>&#39;,</li><li><code>modify_user</code> VARCHAR(11) DEFAULTNULLCOMMENT &#39;</li></ul><p>修改人</p><p>&#39;, PRIMARYKEY (<code>id</code>) ) ENGINE =INNODB AUTO_INCREMENT =1DEFAULTCHARSET =utf8mb4; <strong>启动项目</strong> 添加<code>Maven</code>配置和<code>SQL</code>脚本后，即可启动项目。 若启动成功，则出现如下信息：</p><p>查看数据库，生成了<code>flyway-schema-history</code>表，该表用于记录执行的<code>SQL</code>信息。如下：</p><p>该表名可以通过配置<code>spring.flyway.table=flyway_schema_history</code>修改。 除该表外还执行了配置的<code>SQL</code>脚本，生成了业务表，如下：</p><p>若初始数据库非空，则会出现如下错误：</p><p>可以通过配置<code>spring.flyway.baseline-on-migrate=true</code>，将当前的数据库结构设为基线版本，<code>SQL</code>脚本在基线版本上执行。</p><p>常用配置</p><ul><li>spring:</li><li>flyway:</li><li><h1 id="-3" tabindex="-1"><a class="header-anchor" href="#-3" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>开启</p><ul><li>flyway</li><li>enabled: true</li><li><h1 id="-4" tabindex="-1"><a class="header-anchor" href="#-4" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>数据库非空时，是否执行基线</p><ul><li>baseline-on-migrate: false</li><li><h1 id="-5" tabindex="-1"><a class="header-anchor" href="#-5" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>执行基线版本号</p><ul><li>baseline-version: 1</li><li><h1 id="-6" tabindex="-1"><a class="header-anchor" href="#-6" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>校验<code>SQL</code>文件是否存在</p><ul><li>check-location: true</li><li><h1 id="sql" tabindex="-1">SQL <a class="header-anchor" href="#sql" aria-label="Permalink to &quot;SQL&quot;">​</a></h1></li></ul><p>文件位置</p><ul><li>locations: classpath:db/migration</li><li><h1 id="sql-1" tabindex="-1">SQL <a class="header-anchor" href="#sql-1" aria-label="Permalink to &quot;SQL&quot;">​</a></h1></li></ul><p>文件前缀</p><ul><li>sql-migration-prefix: V</li><li><h1 id="sql-2" tabindex="-1">SQL <a class="header-anchor" href="#sql-2" aria-label="Permalink to &quot;SQL&quot;">​</a></h1></li></ul><p>文件分隔符</p><ul><li>sql-migration-separator: __</li><li><h1 id="sql-3" tabindex="-1">SQL <a class="header-anchor" href="#sql-3" aria-label="Permalink to &quot;SQL&quot;">​</a></h1></li></ul><p>文件后缀</p><ul><li>sql-migration-suffixes: .sql</li><li><h1 id="-7" tabindex="-1"><a class="header-anchor" href="#-7" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>记录表名称</p><ul><li>table: flyway_schema_history</li><li><h1 id="-8" tabindex="-1"><a class="header-anchor" href="#-8" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>目标版本 <code>target:</code></p><p>总结 至此，我们成功的通过<code>Flyway</code>对数据库版本进行管理。</p></div>',1)])])}const g=e(t,[["render",d]]);export{h as __pageData,g as default};
